L001009	\centerline{ \huge SUPPLEMENTAL MATERIAL}
L001010	
L001011	\vspace{0.2cm}
L001012	\centerline{ \large to}
L001013	
L001014	\vspace{0.2cm}
L001015	\centerline{ \Large Random initial data and average shock time} \centerline{\Large in the
L001016	Fermi-Pasta-Ulam-Tsingou chain}
L001017	
L001018	\vspace{0.2cm}
L001019	\centerline{ \large Matteo Gallone, Ricardo Grande, Antonio Ponno, Stefano Ruffo and Erwan Druais}
L001020	
L001021	\vspace{0.5cm}
L001022	\noindent
L001023	In this Supplemental Material we extend the derivation of the shock-time asymptotics for random phases presented in the main text. We provide detailed proofs of the upper and lower bounds, including all intermediate steps. All quantities appearing in the main text are rigorously defined here, with their role in the derivation made explicit. To improve readability, certain rescalings are introduced to avoid cumbersome formulas involving constants and parameters.
L001024	For clarity, we adopt the following notation: $\mathbb{E}$ denotes expectation, $\mathbb{T}$ the interval $[0,1]$ with periodic boundary conditions ($0\sim 1$), and the superscript $\omega$ indicates the realization of the random process. In particular, $\lambda_0^\omega$ coincides with the function $\lambda(x,0)$ of the main text.
L001025	
L001026	We then proceed to discuss the difference between the route to thermalization in the FPUT chain and the phenomenon of ``tygers'' in the Galerkin-truncated Burgers equation. In particular, we provide a sketch of the derivation of the formation times of``tygers'', as well as their average, for initial data with many random Fourier modes.
L001027	
L001028	We conclude with a short section discussing the numerical analysis of the shock time.
L001029	
L001030	\section{Asymptotics of the shock time for random initial data}
L001031	\renewcommand{\theequation}{S.\arabic{equation}}
L001032	\setcounter{equation}{0}
L001033	
L001034	
L001035	The normalized initial data, up to a reminder of order $\sqrt{\epsilon}$, are
L001036	\begin{eqnarray}
L001037		\lambda_{0,p}^\omega(x)&=&\sum_{k=1}^p \frac{1}{\sqrt{p}} \big(\sin(\psi_k^\omega) \cos(2 \pi k x + \theta_k^\omega)+\cos(\psi_k^\omega) \sin(2 \pi k x + \phi_k^\omega) \big) \, , \\
L001038		\rho_{0,p}^\omega(x)&=& \sum_{k=1}^p \frac{1}{\sqrt{p}} \big(\sin(\psi_k^\omega) \cos(2 \pi k x + \theta_k^\omega)-\cos(\psi_k^\omega) \sin(2 \pi k x + \phi_k^\omega) \big) \, .
L001039	\end{eqnarray}
L001040	Given
L001041	\begin{equation}
L001042		(\tau_{s,\lambda,p}^\omega)^{-1} := \max_{x \in \mathbb{T}} \partial_x \lambda_{0,p}^\omega(x) \, , \qquad (\tau_{s,\rho,p}^\omega)^{-1} := \max_{x \in \mathbb{T}} \partial_x \rho_{0,p}^\omega(x) \, ,
L001043	\end{equation}
L001044	we define the shock time of the system as
L001045	\begin{equation}\label{eq:DefTsApp}
L001046		\tau_{s,p}^\omega := \min\{\tau_{s,\lambda,p}^\omega, \tau_{s,\rho,p}^\omega\} \, .
L001047	\end{equation}
L001048	As a consequence of the fact that $\tau_{s,\lambda,p}^\omega, \tau_{s,\rho,p}^\omega\geq 0$,
L001049	\begin{equation}
L001050		(\tau_{s,p}^\omega)^{-1} = \max \{ (\tau_{s,\lambda,p}^\omega)^{-1}, (\tau_{s,\rho,p}^\omega)^{-1} \} \leq (\tau_{s,\lambda,p}^{\omega})^{-1}+(\tau_{s,\rho,p}^\omega)^{-1} \, .
L001051	\end{equation}
L001052	Since $\tau_{s,\lambda,p}^\omega$ and $\tau_{s,\rho,p}^\omega$ have the same probability distribution, we have
L001053	\begin{equation}\label{eq:TsAndTsLambda}
L001054		\mathbb{E} \left[(\tau_{s,p}^\omega)^{-1} \right] \leq 2 \mathbb{E} \left[(\tau_{s,\lambda,p}^\omega)^{-1} \right] \, .
L001055	\end{equation}
L001056	To simplify the analysis, we introduce the following random variables
L001057	\begin{eqnarray}
L001058		X_p^\omega &:=& \max_{x \in \mathbb{T}} \sum_{k=1}^p \frac{k}{\sqrt{p}} \sin(\psi_k^\omega) \sin(2 \pi k x + \theta_k^\omega) \, , \\
L001059		Y_p^\omega &:=& \max_{x \in \mathbb{T}} \sum_{k=1}^p \frac{k}{\sqrt{p}} \cos(\psi_k^\omega) \cos(2 \pi k x + \phi_k^\omega) \, .
L001060	\end{eqnarray}
L001061	which are related to the $\lambda$ and $\rho$ fields as follows:
L001062	\begin{eqnarray}
L001063		X_p^\omega &=& \frac{1}{2} \max_{x \in \mathbb{T}} \big(\partial_x \lambda_{0,p}^\omega(x)+ \partial_x \rho_{0,p}^\omega(x) \big) \, , \\
L001064		Y_p^\omega&=& \frac{1}{2} \max_{x \in \mathbb{T}} \big(\partial_x \lambda_{0,p}^\omega(x)-\partial_x \rho_{0,p}^\omega(x) \big) \, .
L001065	\end{eqnarray}
L001066	The expectation of the shock time and $\mathbb{E}[X_p^\omega]$ are proportional, as shown by the following inequalities:
L001067	\begin{equation}\label{eq:IneqXTs}
L001068		\mathbb{E}[X_p^\omega] \leq \mathbb{E}[ (\tau_{s,p}^\omega)^{-1}] \leq 4 \mathbb{E}[X_p^\omega] \, .
L001069	\end{equation}
L001070	Indeed,
L001071	\begin{equation}
L001072		\begin{split}
L001073			\mathbb{E}[X_p^\omega] &= \frac{1}{2} \mathbb{E}\Big[\max_{x \in \mathbb{T}}( \partial_x \lambda_{0,p}^\omega(x)-\partial_x \rho_{0,p}^\omega(x))\Big] \leq \frac{1}{2} \mathbb{E}\big[(\tau_{s,\lambda,p}^\omega)^{-1}+(\tau_{s,\rho,p}^\omega)^{-1}\big] \\
L001074			& \overset{\text{\eqref{eq:DefTsApp}}}{\leq} \mathbb{E}\big[(\tau_{s,p}^\omega)^{-1}\big] \overset{\text{\eqref{eq:TsAndTsLambda}}}{\leq} 2 \mathbb{E}[(\tau_{s,\lambda,p}^\omega)^{-1}] \leq 2 \mathbb{E}[X_p^\omega+Y_p^\omega] \leq 4 \mathbb{E}[X_p^\omega] \, ,
L001075		\end{split}
L001076	\end{equation}
L001077	where in the last step we used the fact that $X_p^\omega$ and $Y_p^\omega$ have the same probability distribution. As a consequence of \eqref{eq:IneqXTs}, we know that to estimate $\mathbb{E}[(\tau_{s,p}^\omega)^{-1}]$ it will be sufficient to estimate $\mathbb{E}[X_p^\omega]$.
L001078	
L001079	To estimate $\mathbb{E}[X_p^\omega]$, we introduce a new random variable
L001080	\begin{equation}
L001081		\tilde{\theta}_k^\omega := \left\{\begin{array}{lcl}
L001082			\theta_k^\omega + \pi & \qquad & \text{if $\theta_k^\omega < \pi$} \\
L001083			\theta_k^\omega - \pi & & \text{if $\theta_k^\omega \geq \pi$}
L001084		\end{array}\right.
L001085	\end{equation}
L001086	which is uniformly distributed in $[0,2\pi)$. Then,
L001087	\begin{equation}
L001088		\sin(\psi_k^\omega) \sin(2 \pi k x + \theta_k^\omega) = \sin(\psi_k^\omega) \cos(2 \pi k x + \tilde{\theta}_k^\omega) \, .
L001089	\end{equation}
L001090	We also define
L001091	\begin{equation}
L001092		f_p^\omega(x) := \sum_{k=1}^p k \sin(\psi_k^\omega) \cos(2 \pi k x + \tilde{\theta}_k^\omega) \, ,
L001093	\end{equation}
L001094	so that $\max_{x \in \mathbb{T}} f_p^\omega(x)$ has the same probability distribution as $\sqrt{p} X_p^\omega$. In particular,
L001095	\begin{equation}\label{eq:FandX}
L001096		\mathbb{E}\Big[\max_{x \in \mathbb{T}} f_p^\omega(x) \Big] = \sqrt{p} \, \mathbb{E}[X_p^\omega] \, .
L001097	\end{equation}
L001098	At this point, we reduced the problem of estimating $\mathbb{E}[(\tau_{s,p}^\omega)^{-1}]$ to the problem of estimating $\mathbb{E}[\max_{x \in \mathbb{T}} f_p^\omega(x) ]$.
L001099	
L001100	\subsection{Upper bound: First canonical distance of the random process $\{f_p^\omega(x)\}$}
L001101	In this section, we introduce the first canonical distance of the random process $\{f_p^\omega(x)\}$. The latter is a distance on $\mathbb{T}$ induced by the random process $\{f_p^\omega\}_{x \in \mathbb{T}}$ given by
L001102	\begin{equation}\label{eq:upper-canonical-distance}
L001103		d_p(x,y):=\sqrt{\mathbb{E}\Big[\big(f_p^\omega(x)-f_p^\omega(y)\big)^2\Big]} \, , \qquad x,y \in \mathbb{T} \, .
L001104	\end{equation}
L001105	As we shall show in a while, the geometric properties of the space $(\mathbb{T},d_p)$ are related to the statistics of $\mathbb{E}[\max_{x \in \mathbb{T}} f_p^\omega(x)]$. The key ingredient is the \emph{covering number} $N_p(\varepsilon)$, which is the smallest number of balls in the (pseudo-)distance $d_p$ of radius $\varepsilon>0$ that cover $\mathbb{T}$.
L001106	
L001107	If $\{f_p^\omega(x)\}_{x \in \mathbb{T}}$ were a Gaussian process,
L001108	
L001109	we could rely on Dudley's result \cite{Dudley1967,Talagrand2014} to have
L001110	\begin{equation}\label{eq:DudleyDodo}
L001111		\mathbb{E}\Big[\max_{x \in \mathbb{T}} f_p^\omega(x)\Big] \lesssim \int_0^{\mathrm{diam}_p(\mathbb{T})/2} \sqrt{\log N_p(\varepsilon)} \, d \varepsilon \, .
L001112	\end{equation}
L001113	In our case, such a bound does not apply straightforwardly because our process is not Gaussian. We will now show that a bound like \eqref{eq:DudleyDodo} holds for our process despite the lack of Gaussianity.
L001114	
L001115	Firstly, note that we have an explicit expression for $d_p(x,y)$. More precisely,
L001116	\begin{equation}\label{eq:Dfexplicit}
L001117		d_p(x,y)= \sqrt{\frac{1}{2} \sum_{k=1}^p k^2\Big(1-\cos\big(2 \pi k (x-y)\big)\Big)} \, .
L001118	\end{equation}
L001119	Indeed, starting from the definition,
L001120	\begin{equation}\label{eq:PrimoPassoDf}
L001121		\begin{split}
L001122			(d_p(x,y))^2&= \mathbb{E}[(f_p^\omega(x)-f_p^\omega(y))^2] \\
L001123			&=\mathbb{E}\big[(f_p^\omega(x))^2+(f_p^\omega(y))^2 - 2 f_p^\omega(x) f_p^\omega(y)\big] \\
L001124			&=2 \mathbb{E}\big[(f_p^\omega(x))^2\big] - 2 \mathbb{E}\big[f_p^\omega(x) f_p^\omega(y)\big] \, ,
L001125		\end{split}
L001126	\end{equation}
L001127	where in the last step we used the fact that the process $f_p^\omega$ is stationary. Denoting now with $S_a(p)$ the quantity
L001128	\begin{equation}
L001129		S_a(p)=\sum_{k=1}^p k^a \overset{p \to +\infty}{\sim} p^{a+1} \, ,
L001130	\end{equation}
L001131	we have
L001132	\begin{equation}\label{eq:Fpomegaquadrato}
L001133		\mathbb{E}[(f_p^\omega(x))^2] = \sum_{k=1}^p k^2 \mathbb{E}[\sin^2(\psi_k^\omega)] \mathbb{E}[\cos^2(2 \pi k x + \theta_k^\omega)] = \frac{1}{4} \sum_{k=1}^p k^2 =\frac{1}{4} S_2(p) \, ,
L001134	\end{equation}
L001135	\begin{equation}\label{eq:Fpomegaxy}
L001136		\begin{split}
L001137			\mathbb{E}[f_p^\omega(x) f_p^\omega(y)] &= \sum_{k=1}^p k^2 \mathbb{E}[\sin^2 (\psi_k^\omega)] \mathbb{E}[\cos(2 \pi k x+\theta_k^\omega) \cos(2 \pi k y + \theta_k^\omega)]  \\
L001138			&=\sum_{k=1}^p k^2 \frac{1}{2} \mathbb{E}\left[\frac{\cos(2 \pi k (x+y)+2 \theta_k^\omega)}{2}+\frac{\cos(2 \pi k (x-y))}{2} \right] \\
L001139			&=\frac{1}{4} \sum_{k=1}^p k^2 \mathbb{E}[\cos(2 \pi k (x-y))] =\frac{1}{4} \sum_{k=1}^p k^2 \cos(2 \pi k (x-y)) \, .
L001140		\end{split}
L001141	\end{equation}
L001142	Inserting \eqref{eq:Fpomegaquadrato} and \eqref{eq:Fpomegaxy} into \eqref{eq:PrimoPassoDf}, we obtain
L001143	\begin{equation}\label{eq:Upper-CiuchinoMangiaGrano}
L001144		d_p(x,y)^2 = \frac{1}{2} S_2(p) - \frac{1}{2} \sum_{k=1}^p k^2 \cos(2 \pi k (x-y)) = \frac{1}{2} \sum_{k=1}^p k^2(1-\cos(2 \pi k(x-y))) \, ,
L001145	\end{equation}
L001146	which yields \eqref{eq:Dfexplicit}.
L001147	
L001148	As a next step, we compare the distance $d_p$ with the Euclidean distance $d_e$ defined as
L001149	\begin{equation}
L001150		d_e(x,y) := \min_{m \in \mathbb{Z}}|x-y+m| \, .
L001151	\end{equation}
L001152	Using that, for any $\delta \in (0,2)$ we have $1-\cos(2 \pi k x) \leq 4 \pi^2 (k x)^\delta$, we get
L001153	\begin{equation}\label{eq:DfDeEsteso}
L001154		(d_p(x,y))^2 \lesssim \sum_{k=1}^p k^2 (k d_e(x,y))^\delta = (d_e(x,y))^\delta \sum_{k=1}^p k^{2+\delta} = S_{2+\delta}(p) (d_e(x,y))^\delta \, .
L001155	\end{equation}
L001156	The connection between $d_p$ and $d_e$ will be useful in order to estimate the metric entropy. To do so, let us denote by $M_\eta (\varepsilon)$ the packing number with respect to the distance $d_\eta$, $\eta=e,p$. The packing number is the greatest possible number of elements in an $\varepsilon$-distinguishable subset of $\mathbb{T}$. Recall that an $\varepsilon$-distinguishable set $\{x_j\}_{j \in J}$ is a set of elements $x_j \in \mathbb{T}$ such that $d_\eta(x_j,x_{j'})\geq \varepsilon$ for all $j \neq j'$ in $J$.
L001157	
L001158	Note that, by definition, $M_\eta(\varepsilon) \leq N_\eta(\varepsilon) \leq M_\eta(\varepsilon/2)$. By \eqref{eq:DfDeEsteso}, we have that for any $\delta\in (0,2)$
L001159	\begin{equation}
L001160		d_p(x,y) \lesssim d_e(x,y)^{\frac{\delta}{2}} \sqrt{S_{2+\delta}(p)},
L001161	\end{equation}
L001162	and therefore every $\varepsilon$-separated set in $(\mathbb{T},d_p)$ is $\varepsilon^{\frac{2}{\delta}} (S_{2+\delta}(p))^{-\frac{1}{\delta}}$-separated in $(\mathbb{T},d_e)$. In other words,
L001163	\begin{equation}
L001164		M_p(\varepsilon) \leq M_e \left(\left( \frac{\varepsilon}{\sqrt{S_{2+\delta}(p)}}\right)^{\frac{2}{\delta}} \right) \lesssim \left(\frac{\varepsilon}{\sqrt{S_{2+\delta}(p)}} \right)^{-\frac{2}{\delta}} \, .
L001165	\end{equation}
L001166	As a neat result,
L001167	\begin{equation}\label{eq:EntropyEstimateeee}
L001168		N_p(\varepsilon) \lesssim \left(\frac{\sqrt{S_{2+\delta}(p)}}{\varepsilon} \right)^{\frac{2}{\delta}} \, , \qquad \forall \varepsilon>0,\  0<\delta<2 \, .
L001169	\end{equation}
