L001171	\subsection{Upper bound: chaining argument and Dudley's bound}
L001172	As we already mentioned, to bound from above $\mathbb{E}[\max_{x \in \mathbb{T}} f_p^\omega(x)]$ we can not use directly Dudley's bound because our random variables are not Gaussian. The key idea to prove a bound like \eqref{eq:DudleyDodo} exploits the intuition that the tails of the probability distribution of $\max_{x \in \mathbb{T}} f_p^\omega(x)$ are subGaussian. This is to say that, in the end, the estimate will rely on an estimate of the tails
L001173	\begin{equation}
L001174		\mathbb{P}\Big(\max_{x \in \mathbb{T}} f_p^\omega(x) > \lambda\Big) \, , \qquad \text{as } \lambda \to +\infty \, .
L001175	\end{equation}
L001176	
L001177	Let us recall that, if $Z^\omega$ is a nonnegative random variable, by Cavalieri's principle
L001178	\begin{equation}
L001179		\mathbb{E}[Z^\omega] = \int_0^{+\infty} \mathbb{P}(Z^\omega > \lambda) \, d\lambda \, .
L001180	\end{equation}
L001181	Thinking of the integral as the limit of a Riemann sum, we might start by finding a good bound for $\mathbb{P}(\max_{i=1,\dots,n} f_p^\omega(x_i) > \lambda)$. Using a simple ``union bound'', one has
L001182	\begin{equation}\label{eq:ToBeImproved}
L001183		\mathbb{P}\Big(\max_{i=1,\dots,n} f_p^\omega(x_i) > \lambda\Big) \leq \sum_{i=1}^n \mathbb{P}(f_p^{\omega}(x_i) > \lambda) \, .
L001184	\end{equation}
L001185	This latter bound, as it is, is not precise enough because the RHS diverges as $n \to +\infty$. In order to make the idea work and to consider the bound over an infinite set, one needs to exploit two ingredients:
L001186	\begin{itemize}
L001187		\item[(i)] continuity of the function $x \mapsto f_p^\omega(x)$
L001188		\item[(ii)] a large overlap between some sets $\{f_p^\omega(x_i)>\lambda\}$ and $\{f_p^\omega(x_j)>\lambda\}$ if $x_i$ and $x_j$ are close. This latter point means that \eqref{eq:ToBeImproved} is wasteful and one can have better bounds exploiting this overlap.
L001189	\end{itemize}
L001190	
L001191	We now show that the vicinity of two points in item (ii) is best measured in terms of the first canonical distance. In particular, we prove that
L001192	\begin{equation}\label{eq:TesiLemma1}
L001193		\mathbb{P}\big(|f_p^\omega(x)-f_p^\omega(y)|>\lambda\big) \leq 2 \exp \left(-\frac{\lambda^2}{8 d_p(x,y)^2} \right) \, .
L001194	\end{equation}
L001195	Indeed, we have
L001196	\begin{equation}\label{eq:EquationF}
L001197		\begin{split}
L001198			f_p^\omega(x)-f_p^\omega(y) &=\sum_{k=1}^p k \sin(\psi_k^\omega) \Big(\cos(2 \pi k x + \theta_k^\omega)-\cos(2 \pi k y+\theta_k^\omega) \Big) \\
L001199			&=\sum_{k=1}^p 2 k \sin(\psi_k^\omega) \sin\Big({\textstyle \frac{2 \pi k (y-x)}{2}}\Big) \sin\Big({\textstyle \frac{2 \pi k (x+y)}{2}+\theta_k^\omega}\Big) \, .
L001200		\end{split}
L001201	\end{equation}
L001202	For any $z>0$, we have the following Chernoff bound
L001203	\begin{equation}\label{eq:Chernoff}
L001204		\begin{split}
L001205			\mathbb{P}(f_p^\omega(x)-f_p^\omega(y) > \lambda) &\leq e^{-\lambda z} \mathbb{E} \left[ \exp \left(\sum_{k=1}^p 2 k z \sin (\psi_k^\omega) \sin\Big({\textstyle \frac{2 \pi k(y-x)}{2}}\Big)\sin\Big(\theta_k^\omega+{\textstyle \frac{2 \pi k (x+y)}{2}}\Big) \right) \right] \\
L001206			&= \exp(-\lambda z) \prod_{k=1}^p \mathbb{E}\left[ \exp \left( 2 k z \sin (\psi_k^\omega) \sin\big({\textstyle \frac{2 \pi k(y-x)}{2}}\big)\sin\big(\theta_k^\omega+{\textstyle \frac{2 \pi k (x+y)}{2}}\big)\right)\right]
L001207		\end{split}
L001208	\end{equation}
L001209	Let us note that for any $\alpha \in \mathbb{R}$, we have
L001210	\begin{equation}
L001211		\begin{split}
L001212			\mathbb{E}\big[\exp(\alpha \sin(\psi_k^\omega) \sin(\theta_k^\omega))\big]&= \frac{1}{4 \pi^2} \int_0^{2 \pi} \int_0^{2 \pi} e^{\alpha \sin \theta \sin \psi} \, d\psi d \theta \\
L001213			&= \frac{1}{2 \pi^2} \int_0^\pi \int_0^\pi (e^{\alpha \sin \theta \sin \psi}+e^{-\alpha \sin \theta \sin \psi}) \, d\theta d \psi \\
L001214			&=\frac{1}{\pi^2} \int_0^\pi \int_0^\pi \cosh(\alpha \sin \theta \sin \psi) \, d\theta d \psi \\
L001215			&\leq \frac{1}{\pi^2}\int_0^\pi \int_0^\pi \exp\left(\frac{\alpha^2}{2}\, \sin^2\psi\, \sin^2 \theta\right) \, d \theta d \psi \leq e^{\frac{\alpha^2}{2}}
L001216		\end{split}
L001217	\end{equation}
L001218	Using the latter inequality in \eqref{eq:Chernoff}, we have
L001219	\begin{equation}
L001220		\begin{split}
L001221			\mathbb{P}(f_p^\omega(x)-f_p^\omega(y) > \lambda) & \leq e^{-\lambda z} \prod_{k=1}^p \exp\left(\frac{4 k^2 z^2 \sin^2(\frac{2 \pi k (y-x)}{2})}{2} \right) \\
L001222			&\leq \exp\left(-\lambda z +z^2 \sum_{k=1}^p 2 k^2 \sin^2\big({\textstyle \frac{2 \pi k (y-x)}{2}}\big) \right) \\
L001223			&=\exp\left(-\lambda z+z^2 \sum_{k=1}^p(1-\cos(2 \pi k (y-x))) \right) = \exp(-\lambda z + 2 z^2 d_p(x,y)^2)
L001224		\end{split}
L001225	\end{equation}
L001226	Choosing now $z=\frac{\lambda}{4 d_p(x,y)^2}$ yields \eqref{eq:TesiLemma1}.
L001227	
L001228	At this point, we are ready to give the main strategy to bound $\mathbb{P}(\max_{x \in \mathbb{T}} f_p^\omega(x))$. The idea is to construct finite subsets $\mathcal{N}_n \subset \mathbb{T}$ whose points are closer as closer when $n$ increases. For $r \in (0,1)$, choose $\mathcal{N}_n$ such that
L001229	\begin{equation}
L001230		d_p(x,\mathcal{N}_n) \lesssim r^n \, ,\qquad \forall x \in \mathbb{T} \, , \qquad \forall n \in \mathbb{N} \, .
L001231	\end{equation}
L001232	The existence of the set $\mathcal{N}_n$ with such properties is guaranteed by the compactness of $(\mathbb{T},d_p)$.
L001233	
L001234	On $\mathbb{T}$, we define projections $\pi_n:\mathbb{T} \to \mathcal{N}_n$ so that $\pi_n(x)$ is the closest point to $x$ in $\mathcal{N}_n$, with distance measured in $d_p$. With these tools at hand, we can decompose $f_p^\omega$ along the chain $\{\pi_n(x)\}_{n\in\mathbb{N}_0}$, i.e.
L001235	\begin{equation}
L001236		f_p^\omega(x) = f_p^\omega(\pi_0(x))+\sum_{n=1}^{\infty} \big(f_p^\omega(\pi_n(x))-f_p^\omega(\pi_{n-1}(x))\big) \, .
L001237	\end{equation}
L001238	Then,
L001239	\begin{equation}
L001240		\max_{x \in \mathbb{T}} f_p^\omega(x) \leq \max_{x \in \mathbb{T}} f_p^\omega(\pi_0(x))+\sum_{n=1}^\infty \max_{x \in \mathbb{T}} \left(f^\omega(\pi_n(x))-f^\omega(\pi_{n-1}(x)) \right)
L001241	\end{equation}
L001242	where now each supremum is over a maximum over a finite set.
L001243	
L001244	To estimate each of the differences $f_p^\omega(\pi_n(x))-f_p^\omega(\pi_{n-1}(x))$ we will use \eqref{eq:TesiLemma1}. For the sum $\sum_{n=1}^\infty$ we will use the following idea. If $Z_n^\omega$ is a random variable,
L001245	\begin{equation}
L001246		\mathbb{P}\Big(\sum_{n=1}^\infty |Z_n^\omega| > \lambda\sigma\Big) \leq \sum_{n=1}^\infty \mathbb{P}\big(|Z_n^\omega| > \lambda \sigma_n\big)
L001247	\end{equation}
L001248	where $(\sigma_n)_{n=1}^\infty \subset \mathbb{R}_+$ is any sequence such that $\sigma=\sum_{n=1}^\infty \sigma_n <\infty$. For $r\in (0,\frac18)$ sufficiently small, set
L001249	\begin{equation}
L001250		\sigma_n = (8r)^n \sqrt{\log(2^n |\mathcal{N}_n| |\mathcal{N}_{n-1}|)} \, , \qquad n \in \mathbb{N} \, .
L001251	\end{equation}
L001252	Since $\sigma=\sum_{n=1}^\infty \sigma_n < +\infty$, which we explain in \eqref{eq:sigma_finite} below, we have
L001253	\begin{equation}
L001254		\begin{split}
L001255			\mathbb{P}\big(\max_{x \in \mathbb{T}} |f_p^\omega(x)-f_p^\omega(0)|> \lambda \sigma\big) & \leq \mathbb{P}\Big(\sum_{n=1}^\infty \max_{x \in \mathbb{T}} |f_p^\omega(\pi_n(x))-f_p^\omega(\pi_{n-1}(x))> \lambda \sigma\Big) \\
L001256			&\leq \sum_{n=1}^\infty \mathbb{P}\big(\exists x \in \mathbb{T} \, : \, |f_p^\omega(\pi_n(x))-f_p^\omega(\pi_{n-1}(x))| > \lambda \sigma_n\big) \\
L001257		&\lesssim \sum_{n=1}^\infty |\mathcal{N}_n| | \mathcal{N}_{n-1}| \exp\left(-\frac{(\lambda \sigma_n)^2}{8 (d_p(\pi_n(x), \pi_{n-1}(x))^2} \right)\\
L001258			&\leq \sum_{n=1}^\infty |\mathcal{N}_n| |\mathcal{N}_{n-1}| (|\mathcal{N}_{n}| | \mathcal{N}_{n-1}|)^{-\lambda^2} 2^{-n \lambda^2} \\
L001259		&\lesssim \sum_{n=1}^\infty 2^{-n \lambda^2} \lesssim 2^{-\lambda^2} \, , \qquad \text{for $\lambda>1$} \, .
L001260		\end{split}
L001261	\end{equation}
L001262	Finally, we obtain
L001263	\begin{equation}
L001264		\begin{split}
L001265			\mathbb{E}\big[\max_{x \in \mathbb{T}} |f_p^\omega(x)-f_p^\omega(0)|\big] &=\int_0^\infty \mathbb{P}\Big(\max_{x \in \mathbb{T}} |f_p^\omega(x)-f_p^\omega(0)| > \lambda\Big) \, d\lambda \\
L001266			&=\sigma \int_0^\infty \mathbb{P}\Big(\max_{x \in \mathbb{T}} |f_p^\omega(x)-f_p^\omega(0)| > \sigma \tilde{\lambda}\Big) \, d \tilde{\lambda} \\
L001267			&\lesssim \sigma \left( \int_0^1 d\tilde{\lambda}+\int_1^\infty 2^{-\tilde{\lambda}^2} \, d \tilde{\lambda}\right) \lesssim \sigma \, .
L001268		\end{split}
L001269	\end{equation}
L001270	Similarly,
L001271	\begin{equation}
L001272		\mathbb{E}\Big[\max_{x \in \mathbb{T}} f_p^\omega(x)\Big] \leq \mathbb{E}\Big[\max_{x \in \mathbb{T}} \big|f_p^\omega(x)-f_p^\omega(0)\big|\Big]+\mathbb{E}\big[|f_p^\omega(0)|\big] \lesssim \sigma + \sqrt{S_2(p)} \, .
L001273	\end{equation}
L001274	Since $\sqrt{S_2(p)} \sim p^{\frac{3}{2}}$, we need to estimate only $\sigma$. Indeed,
L001275	\begin{equation}\label{eq:sigma_finite}
L001276		\begin{split}
L001277			\sigma &\lesssim \sum_{n=1}^\infty (8r)^n \sqrt{\log (2^n |\mathcal{N}_n ||\mathcal{N}_{n-1}|)} \\
L001278			&\leq \sum_{n=1}^\infty (8r)^n (\sqrt{n} \sqrt{\log 2} + \sqrt{\log|\mathcal{N}_n|} + \sqrt{\log|\mathcal{N}_{n-1}|}) \\
L001279			&\lesssim \sum_{n=1}^\infty (8r)^n \sqrt{\log| \mathcal{N}_n|} \sim \int_0^{\mathrm{diam}_p(\mathbb{T})/2} \sqrt{\log N_p(\varepsilon)} \, d\varepsilon
L001280		\end{split}
L001281	\end{equation}
L001282	and we are left in estimating this latter integral. Indeed, noting that $\mathrm{diam}_p(\mathbb{T})/2 \sim \sqrt{S_2(p)}$, we get.
L001283	\begin{equation}
L001284		\begin{split}
L001285			\sigma & \lesssim \int_0^{\sqrt{S_2(p)}} \sqrt{\log N_p(\varepsilon)} \, d\varepsilon \\
L001286			&\hspace{-0.2cm}\overset{\text{\eqref{eq:EntropyEstimateeee}}}{\lesssim} \int_0^{\sqrt{S_2(p)}} \sqrt{\frac{2}{\delta} \log \left(\frac{\sqrt{S_{2+\delta}(p)}}{\varepsilon} \right)} \, d \varepsilon \\
L001287			&\hspace{-0.8cm}\overset{\varepsilon=\sqrt{S_{2+\delta}(p)}e^{-z}}{=} \frac{2}{\sqrt{\delta}} \int_{\log \sqrt{\frac{S_{2+\delta}(p)}{S_2(p)}}}^{+\infty} \sqrt{z} e^{-z} \sqrt{S_{2+\delta}(p)} \, d z \\
L001288			&\lesssim \frac{1}{\sqrt{\delta}} \sqrt{S_{2+\delta}(p)} \int_0^{+\infty} \sqrt{z} e^{-z} \, dz \\
L001289			&\lesssim \frac{1}{\sqrt{\delta}} \sqrt{S_{2+\delta}(p)} \\
L001290			&\lesssim \frac{1}{\sqrt{\delta}} p^{\frac{3}{2}+\frac{\delta}{2}}  \end{split}
L001291	\end{equation}
L001292	Choosing now $\delta=2 (\log p)^{-1}$, we have $p^\delta=p^{(\log p)^{-1}}=e$. This proves the following
L001293	\begin{equation}
L001294		\mathbb{E}\Big[\max_{x \in \mathbb{T}} |f_p^\omega(x)|\Big] \lesssim p^{\frac{3}{2}} \sqrt{\log p} \, .
L001295	\end{equation}
L001296	Whence, using \eqref{eq:FandX}, we get $\mathbb{E}[X_p^\omega] \lesssim p \sqrt{\log p}$ and, by \eqref{eq:IneqXTs} we complete the proof of the upper bound
L001297	\begin{equation}
L001298		\mathbb{E}\big[(\tau_{s,p}^\omega)^{-1}\big] \lesssim p \sqrt{\log p} \, .
L001299	\end{equation}
L001300	
L001301	\subsection{Lower bound: second canonical distance}
L001302	The construction of a sharp lower bound for $\mathbb{E}[\max_{x \in \mathbb{T}} f_p^\omega(x)]$ is more delicate than the upper bound. At first we note that
L001303	\begin{equation}\label{eq:pingiuno_nucleare}
L001304		\max_{x \in \mathbb{T}} |f_p^\omega(x)| \leq \max_{x \in \mathbb{T}} f_p^\omega(x)+\max_{x \in \mathbb{T}} \big( - f_p^\omega(x)\big) \, .
L001305	\end{equation}
L001306	Then, since $f_p^\omega(x)$ and $-f_p^\omega(x)$ have the same probability distribution, we can take the expectation on both sides of \eqref{eq:pingiuno_nucleare} to get
L001307	\begin{equation}
L001308		\mathbb{E}\Big[ \max_{x \in \mathbb{T}} f_p^\omega(x) \Big] \leq \mathbb{E} \Big[ \max_{x \in \mathbb{T}} f_p^\omega(x) \Big] + \mathbb{E}\Big[ \max_{x \in \mathbb{T}} \big(-f_p^\omega(x)\big) \Big] = 2 \mathbb{E} \Big[ \max_{x \in \mathbb{T}} f_p^\omega(x) \Big] \, ,
L001309	\end{equation}
L001310	so that
L001311	\begin{equation}\label{eq:lower-star}
L001312		\mathbb{E}\Big[ \max_{x \in \mathbb{T}} f_p^\omega(x) \Big] \geq \frac{1}{2} \mathbb{E} \Big[ \max_{x \in \mathbb{T}} |f_p^\omega(x)| \Big] \, .
L001313	\end{equation}
L001314	We now introduce an auxiliary random process $g_p^\omega$ and conveniently rewrite $f_p^\omega$ as
L001315	\begin{equation}\label{eq:lower-asterisco}
L001316		\begin{split}
L001317			f_p^\omega(x)&= \Ree \Big(\sum_{k=1}^p k \sin(\psi_k^\omega ) e^{i \tilde{\theta}_k^\omega} e^{2 \pi i k x} \Big) \, , \\
L001318			g_p^\omega(x)&= \Imm \Big(\sum_{k=1}^p k \sin(\psi_k^\omega) e^{i \tilde{\theta}_k^\omega} e^{2 \pi i j x} \Big) \, .
L001319		\end{split}
L001320	\end{equation}
L001321	From the explicit expressions of $f_p^\omega$ and $g_p^\omega$, one sees that the two processes have the same probability distribution. Moreover,
L001322	\begin{equation}\label{eq:lower-anonima}
L001323		\max_{x \in \mathbb{T}} \sqrt{\big( f_p^\omega(x) \big)^2+\big(g_p^\omega(x) \big)^2} \leq \sqrt{2} \max_{x \in \mathbb{T}} \max\Big\{ |f_p^\omega(x) | , |g_p^\omega(x)| \Big\} \leq \sqrt{2} \Big( \max_{x \in \mathbb{T}} |f_p^\omega(x) | + \max_{x \in \mathbb{T}} |g_p^\omega(x)| \Big) \, .
L001324	\end{equation}
L001325	Using \eqref{eq:lower-asterisco} and the fact that $g_p^\omega$ and $f_p^\omega$ have the same probability distribution, from \eqref{eq:lower-anonima} we get
L001326	\begin{equation}\label{eq:lower-quadrato}
L001327		\mathbb{E} \Big[ \max_{x \in \mathbb{T}} \sqrt{\big( f_p^\omega(x) \big)^2+\big(g_p^\omega(x) \big)^2} \Big] \leq 2 \sqrt{2}\, \mathbb{E} \Big[ \max_{x \in \mathbb{T}} |f_p^\omega(x)| \Big] \, .
L001328	\end{equation}
L001329	Noting that
L001330	\begin{equation}\label{eq:lower-triangolo}
L001331		\mathbb{E}\Big[ \max_{x \in \mathbb{T}} \sqrt{\big( f_p^\omega(x) \big)^2+\big(g_p^\omega(x) \big)^2} \Big] = \mathbb{E} \Big[ \max_{x \in \mathbb{T}} \Big| \sum_{k=1}^p k \sin(\psi_k^\omega) e^{i \tilde{\theta}_k^\omega} e^{2 \pi i k x} \Big| \Big] \, ,
L001332	\end{equation}
L001333	and combining \eqref{eq:lower-star}, \eqref{eq:lower-quadrato} and \eqref{eq:lower-triangolo} we get
L001334	\begin{equation}\label{eq:lower-flower}
L001335		\mathbb{E}\Big[ \max_{x \in \mathbb{T}} f_p^\omega(x) \Big] \geq \frac{1}{2} \mathbb{E}\Big[\max_{x \in \mathbb{T}} | f_p^\omega(x) | \Big] \geq \frac{1}{4 \sqrt{2}} \mathbb{E} \Big[\max_{x \in \mathbb{T}} \Big|\sum_{k=1}^p k \sin(\psi_k^\omega) e^{i \tilde{\theta}_k^\omega} e^{2 \pi i k x} \Big| \Big] \, .
L001336	\end{equation}
L001337	All that remains is to find a lower bound for the RHS of \eqref{eq:lower-flower}. Since $\tilde{\theta}_k^\omega$ and $\psi_{k'}^\omega$ are independent random variables for every $k$ and $k'$, we can decompose the probability space $\Omega$ as $\Omega=\Omega_1 \times \Omega_2$ in such a way that $\psi_k^\omega=\psi_k^{\omega_1}$ and $\tilde{\theta}_k^\omega=\tilde{\theta}_k^{\omega_2}$. According to this decomposition, the probability measure is factorized as $\mathbb{P}=\mathbb{P}_1 \otimes \mathbb{P}_2$.
L001338	
L001339	Denoting now with $\mathbb{E}_1$ the average over $\Omega_1$ only, we study
L001340	\begin{equation}\label{eq:lower-A}
L001341		\mathbb{E}_1 \Big[ \max_{x \in \mathbb{T}} \Big| \sum_{k=1}^p k \sin(\psi_k^{\omega_1}) e^{i \tilde{\theta}_k^{\omega_2}} e^{2 \pi i k x} \Big| \Big].
L001342	\end{equation}
L001343	One can define a canonical distance for this process, different from the one defined in \eqref{eq:upper-canonical-distance} (see \cite[Proposition 3.2.15]{Talagrand2014}):
L001344	\begin{equation}\label{eq:lower-UUUIO}
L001345		\begin{split}
