L001548	\section{Generation of tygers for many-modes initial data}
L001549	As a corollary of our main result, we show how the choice of phases affects the time of formation of tygers in the truncated Burgers equation. The argument for a single mode solution can be found in Appendix B of \cite{Ray2011} and, for two modes solution, in Section IV.B of \cite{Rampf2022}.
L001550	
L001551	It is well-known that the solution to the initial value problem of the inviscid Burgers equation
L001552	\begin{equation}\label{eq:BurgersAPP}
L001553	    \left\{\begin{array}{l}
L001554	        u_t(t,x)=u(t,x) u_x(t,x) \\
L001555	        u(0,x)=u_0(x)
L001556	        \end{array}
L001557	    \right.
L001558	\end{equation}
L001559	for $x \in \mathbb{T}$
L001560	exists, as a function in a strong sense, only for $0\leq t \leq t_s$. A lot of research effort has been spent in the Galerkin-truncated Burgers equation
L001561	\begin{equation}
L001562	    u_t(t,x)=P_K(u(t,x) u_x(t,x)) \, .
L001563	\end{equation}
L001564	If the initial datum is analytic, any solution to \eqref{eq:BurgersAPP} is analytic until the shock time. In particular, if the initial datum is a Fourier polynomial, the solution to the Burgers equation is analytic on a strip of width $\delta(t)$. This implies, in particular, that
L001565	\begin{equation}\label{eq:AnaliticityBurgers}
L001566	    |\hat{u}_k(t)| \lesssim e^{-\delta(t) |k|} \, .
L001567	\end{equation}
L001568	Due to the fact that the cutoff introduced by the Galerkin truncation $P_K$ projects on Fourier modes with $|k| \leq K$, and due to \eqref{eq:AnaliticityBurgers}, it follows that the difference between the solution to the Galerkin truncated Burgers equation and the solution to the inviscid Burgers equation are undistinguishable until $\delta(t) K \sim 1$, that is until the time the poles of the solution intersects the horizontal line in the complex plane $\pm i K^{-1}$. This latter time coincides with the time of formation of the tygers (this is -- in short -- the argument of \cite{Ray2011}).
L001569	
L001570	It is also well-known, both theoretically and numerically, that such a time -- for one-mode solution -- behaves as
L001571	\begin{equation}
L001572	    t_G=t_s-K^{-\frac{2}{3}} \, .
L001573	\end{equation}
L001574	In this section, we analyze the tygers formation time for the class of initial solutions we used for FPUT.
L001575	
L001576	The first thing to do, is to compute $t_G$ for generic solutions. This can be done by generalizing the argument of Appendix B in \cite{Ray2011} or following \cite{Rampf2022}.
L001577	
L001578	The position of the pole in $\xi \in \mathbb{C}$ coordinates is given by the vanishing of the Jacobian of the transformation $x=\xi-u_0(\xi) t$ with $x \in \mathbb{C}$ and $t \in \mathbb{R}$. The condition
L001579	\begin{equation}
L001580	    \partial_\xi x = 0 \qquad \Leftrightarrow \qquad 1 - u'_0(\xi) t = 0
L001581	\end{equation}
L001582	Calling now $\xi_* \in \mathbb{R}$ the point where the first pole hits the real line, by definition of the shock time we have $t_s=\frac{1}{u'_0(\xi_*)}$, which yields also $1=u'_0(\xi_*) t_s$. By expanding $u_0'(\xi)$ around $\xi_*$ we have
L001583	\begin{equation}
L001584	    u'_0(\xi_*) t_s-u'_0(\xi_*) t-\frac{1}{2}u_0'''(\xi_*)(\xi-\xi_*)^2 t_s-\frac{1}{2}u_0'''(\xi_*)(\xi-\xi_*)^2(t-t_s)+\cdots = 0
L001585	\end{equation}
L001586	where we assumed a genericity condition $u_0'''(\xi_*) \neq 0$.
L001587	Using now the fact that $t-t_s$ is small, we obtain, up to higher order terms, the equation to solve in $\xi$
L001588	\begin{equation}
L001589	    u'_0(\xi_*)(t_s-t)-\frac{1}{2}u_0'''(\xi_*)(\xi-\xi_*)^2 t_s = 0 \, .
L001590	\end{equation}
L001591	The latter yields
L001592	\begin{equation}\label{eq:PoliXi}
L001593	    \xi-\xi_*= \pm \sqrt{\frac{2(t_s-t)u_0'(\xi_*)}{u_0'''(\xi_*)t_s}}=\pm \frac{i}{t_s}\sqrt{\frac{2(t_s-t)}{|u_0'''(\xi_*)| }}
L001594	\end{equation}
L001595	where in the last step we used the fact that, since $\xi_*$ is a maximum for the first derivative, then $(u_0')''(\xi_*) \leq 0$.
L001596	
L001597	We now insert \eqref{eq:PoliXi} into $x=\xi-u_0(\xi) t$ to compute the poles in the $x$ variables. The formation of the tyger is related to the time where the poles are at $\Im x=\pm i K^{-1}$. Thus,
L001598	\begin{equation}
L001599	    \begin{split}
L001600	    x_*&=\xi-\xi_*+\xi_* -u_0(\xi_*) t -u'_0(\xi_*)(\xi-\xi_*)t - \frac{1}{6}u_0'''(\xi_*)(\xi-\xi_*)^3 t_s + \cdots \\
L001601	    &=\xi_*- u_0(\xi_*) t +u'_0(\xi_*)(\xi-\xi_*)(t_s-t)-\frac{1}{6} u_0'''(\xi_*)(\xi-\xi_*)^3t_s+ \cdots \\
L001602	    &=\xi_*- u_0(\xi_*) t +\frac{1}{t_s}(\xi-\xi_*)(t_s-t)-\frac{1}{6} u_0'''(\xi_*)(\xi-\xi_*)^3t_s+ \cdots
L001603	    \end{split}
L001604	\end{equation}
L001605	Taking now the imaginary part at both sides, one gets
L001606	\begin{equation}
L001607	    \begin{split}
L001608	        K^{-1}&=\frac{1}{t_s^2} \sqrt{\frac{2}{|u_0'''(\xi_*)|}}(t_s-t)^{\frac{3}{2}}-\frac{1}{3 t_s^2} \sqrt{\frac{2}{|u_0'''(\xi_*)|}}(t_s-t)^{\frac{3}{2}}+ \cdots \\
L001609	        &=\frac{2 \sqrt{2}}{3 t_s^2} \frac{1}{\sqrt{|u_0'''(\xi_*)|}} (t_s-t)^{\frac{3}{2}} \, .
L001610	    \end{split}
L001611	\end{equation}
L001612	which yields
L001613	\begin{equation}
L001614	    t_s-t=\left(\frac{3 }{2\sqrt{2}}  \right)^{\frac{2}{3}} |u_0'''(\xi_*)|^{\frac{1}{3}} t_s^{\frac{4}{3}}K^{-\frac{2}{3}}
L001615	\end{equation}
L001616	This implies
L001617	\begin{equation}
L001618	    t_G=t_s\left[ 1-\left(\frac{3}{2 \sqrt{2}}\right)^{\frac{2}{3}} |u_0'''(\xi_*)|^{\frac{1}{3}} t_s^{\frac{1}{3}} K^{-\frac{2}{3}}\right]
L001619	\end{equation}
L001620	which agrees with Eq.~(B5) in \cite{Ray2011} when the initial datum is a sine-wave. Let us now check what happens for the initial data of our problem, that is when
L001621	\begin{equation}
L001622	    u(x)=\frac{1}{\sqrt{p}} \sum_{k=1}^p  \cos(2 \pi k x + \theta_k^\omega)
L001623	\end{equation}
L001624	When all $\theta_k^\omega=0$, that is the case of coherent phases, we obtain
L001625	\begin{equation}
L001626	    t_s^{-1}=u'(0)=\frac{1}{\sqrt{p}}\sum_{k=1}^p (2 \pi k)=\sqrt{p}(p+1) \pi \, , \qquad u_0'''(0)=-\frac{1}{\sqrt{p}} \sum_{k=1}^p(2 \pi k)^3=-2 p^{\frac{3}{2}}(1+p)^2 \pi^3
L001627	\end{equation}
L001628	therefore, one obtains as the time of formation of the first tyger the explicit expression
L001629	\begin{equation}
L001630	    t_G=\frac{1}{\sqrt{p}(p+1) \pi} \left[1-\left(\frac{3}{2} \right)^{\frac{2}{3}} \pi \sqrt{p}(1+p)^{\frac{2}{3}} K^{-\frac{2}{3}} \right]
L001631	\end{equation}
L001632	In particular, the last equation says that, with respect to the shock time, one has
L001633	\begin{equation}
L001634	    1-\frac{t_G}{t_s}=\left(\frac{3}{2}\right)^{\frac{2}{3}} \pi \sqrt{p}(1+p)^{\frac{2}{3}}K^{-\frac{2}{3}} \, .
L001635	\end{equation}
L001636	
L001637	When random initial data are taken, in general the behavior is much different. Indeed, on average, one has the following upper bound
L001638	\begin{equation}
L001639	    1-\mathbb{E}\left[ \frac{t_G}{t_s}\right] =\left(\frac{3}{2\sqrt{2}}\right)^{\frac{2}{3}} \mathbb{E}\left[|u_0'''(\xi_*)|^{\frac{1}{3}} t_s^{\frac{1}{3}}\right] K^{-\frac{2}{3}}
L001640	\end{equation}
L001641	Using that $t_s \leq \frac{1}{p}$, that is because
L001642	\begin{equation}
L001643	    t_s = \frac{1}{\sup_\xi u_0'(\xi)} \lesssim \frac{1}{p}
L001644	\end{equation}
L001645	because $\sup_\xi (u_0')^2 \geq \int_0^1 u_0'(\xi)^2 \, d\xi = \frac{1}{p\sqrt{2}}\sum_{k=1}^p  (2 \pi k)^2$ where in the last step we used the Parseval identity.
L001646	
L001647	we get
L001648	\begin{equation}
L001649	    \mathbb{E}\left[|u_0'''(\xi_*)|^{\frac{1}{3}} \right] p^{-\frac{1}{3}} \leq \mathbb{E}\Big[ \sup_{\xi} |u_0'''(\xi)|^{\frac{1}{3}} \Big] p^{-\frac{1}{3}}
L001650	\end{equation}
L001651	Using H\"older inequality, we have $\mathbb{E}\Big[ \sup_{\xi} |u_0'''(\xi)|^{\frac{1}{3}}\Big] \leq \mathbb{E}\left[ \sup_{\xi} u_0'''(\xi) \right]^{\frac{1}{3}}$. One can now estimate $\mathbb{E}\left[ \sup_\xi u_0'''(\xi) \right]$ as we did for $\mathbb{E}[\sup_{\xi}u_0'(\xi)]$ above, to get
L001652	\begin{equation}
L001653	    \mathbb{E}\Big[ \sup_\xi u_0'''(\xi) \Big]^{\frac{1}{3}} \lesssim p^{\frac{7}{6}} (\log p)^{\frac{1}{6}} \, .
L001654	\end{equation}
L001655	We thus obtained
L001656	\begin{equation}
L001657	   0\leq 1-\mathbb{E}\left[\frac{t_G}{t_s} \right] \lesssim p^{\frac{5}{6}} (\log p)^{\frac{1}{6}} \, K^{-\frac{2}{3}} \, .
L001658	\end{equation}
L001659	with a constant independent of $p$ and $K$. In particular, the right-hand side is small whenever $K \gtrsim p^{\frac{5}{4}} (\log p)^{\frac{1}{4}}$.
