L001801	\section{Introduction}
L001802	
L001803	Consider a random function of the form
L001804	\begin{equation}
L001805		f_{\omega,p}(x)=\sum_{k=1}^p k \sin \psi_k \cos (2 \pi k x +\theta_k^\omega)
L001806	\end{equation}
L001807	with $x \in [0,1)$ and $\omega \in \Omega$ where $(\Omega, \mathcal{F}, \mathbb{P})$ is a probability space. The random variables $\{\theta_k\}_{k=1}^p$ and $\{\psi_k\}_{k=1}^p$ are i.i.d.~and uniformly distributed on $[0,2\pi]$.
L001808	
L001809	The asymptotics of the shock time can be obtained from an upper and a lower bound for the quantity
L001810	\begin{equation}\label{eq:FomegaPSUP}
L001811		\mathbb{E}\left[\sup_{x \in (0,2\pi)} f_{p,\omega}(x)\right]
L001812	\end{equation}
L001813	as $p \to +\infty$. We start by noting that
L001814	\begin{equation}
L001815		\begin{split}
L001816			\mathbb{E}[f_{\omega,p}(x)]&= \sum_{k=1}^p k \mathbb{E}[\sin \psi_k] \mathbb{E}[\cos(2 \pi k x+ \theta_k)] \\
L001817			&=\sum_{k=1}^p k \fint_0^{2\pi} \sin y \, dy \fint_0^{2\pi} \cos(2 \pi k x+y) \, dy = 0
L001818		\end{split}
L001819	\end{equation}
L001820	and
L001821	\begin{equation}
L001822		\begin{split}
L001823			\mathbb{E} [f_{p,\omega}(x)^2] & = \sum_{k=1}^p k^2 \mathbb{E}[\sin^2 \psi_j ] \mathbb{E} [\cos^2 (2 \pi k x + \theta_k)] \\
L001824			&=\sum_{k=1}^p k^2 \frac{\pi}{2 \pi} \frac{\pi}{2 \pi} =\frac{p(p+1)(p+\frac{1}{2})}{12} \sim p^3
L001825		\end{split}
L001826	\end{equation}
L001827	From a technical veiwpoint, the main challenge in the estimate of \eqref{eq:FomegaPSUP} is the presence of the $\sup$ \emph{inside} the expectation, since obviously $\mathbb{E}[\sup_x f(x)] \neq \sup_x \mathbb{E}[f(x)]$, in general.
L001828	
L001829	To handle this difficulty, we will carefully use techniques pionereed by Dudley in the 60's and improved by Talagrand and many others in the last 30 years.
L001830	
L001831	\section{Connection with Burgers}
L001832	The function $f_{\omega,p}$ comes from estimating the shock time of the Burgers equation with initial data of the form
L001833	\begin{eqnarray}
L001834		\lambda_0(x) &=&\sum_{k=1}^p \frac{1}{\sqrt{p}} [\sin \psi_k^\omega \cos(2 \pi k x+\theta_k^\omega)+\cos \psi_k^\omega \sin(2 \pi k x +\phi_k^\omega)] \\
L001835		\rho_0(x) &=&\sum_{k=1}^p \frac{1}{\sqrt{p}} [\sin \psi_k^\omega \cos(2 \pi k x+\theta_k^\omega)-\cos \psi_k^\omega \sin(2 \pi k x +\phi_k^\omega)]
L001836	\end{eqnarray}
L001837	and the shock time is the minimum between $\tau_s^\lambda$ and $\tau_s^\rho$. First, let us note that
L001838	\begin{equation}
L001839		\tau_s^{-1}=\max\{(\tau_s^{\lambda})^{-1},(\tau_s^{\rho})^{-1}\} \leq (\tau_s^{\lambda})^{-1}+(\tau_s^{\rho})^{-1} \, .
L001840	\end{equation}
L001841	Since $\psi_k$ is uniformly distributed, then $\cos \psi_k$ and $-\cos \psi_k$ have the same distribution law, and therefore $(\tau_s^{\lambda})^{-1} \sim (\tau_s^{\rho})^{-1}$. We therefore have
L001842	\begin{equation}
L001843		\mathbb{E}[\tau_s^{-1}] \leq 2 \mathbb{E}[(\tau_s^\lambda)^{-1}]
L001844	\end{equation}
L001845	Moreover, let us note also that
L001846	\begin{equation}
L001847		\sup_{x \in [0,1]} (\lambda'_0(x)+\rho_0'(x)) \leq (\tau_{s}^\lambda)^{-1}+(\tau_s^\rho)^{-1} \leq 2 \tau_s^{-1}
L001848	\end{equation}
L001849	and thus
L001850	\begin{equation}
L001851		\frac{1}{2} \mathbb{E}[\sup_x (\lambda'_0(x)+\rho_0'(x))] \leq \mathbb{E}[\tau_s^{-1}] \, .
L001852	\end{equation}
L001853	Let us define $X^\omega$ and $Y^\omega$ as
L001854	\begin{equation}
L001855		X^\omega=\sup_{x \in I} \sum_{k=1}^p \frac{k}{\sqrt{p}} \sin \psi_k^\omega \sin(2 \pi k x+\theta_k^\omega) = \frac{1}{2} \sup_{x \in I} [\lambda_0'(x)+\rho_0'(x)]
L001856	\end{equation}
L001857	\begin{equation}
L001858		Y^\omega=\sup_{x \in I} \sum_{k=1}^p \frac{k}{\sqrt{p}} \cos \psi_k^\omega \cos(2 \pi k x +\phi_k^\omega) = \frac{1}{2} \sup_{x \in I} [\lambda_0'(x)-\rho_0'(x)]
L001859	\end{equation}
L001860	Thus, we have proved that
L001861	\begin{equation}
L001862		\mathbb{E}[X^\omega] \leq \mathbb{E}[\tau_s^{-1}] \leq 2 \mathbb{E}[(\tau_s^\lambda)^{-1}] \leq 2 \mathbb{E}[X^\omega+Y^\omega] = 2 \mathbb{E}[X^\omega] \, .
L001863	\end{equation}
L001864	Therefore, in order to estimate $\mathbb{E}[\tau_s^{-1}]$, it sufficies to estimate $\mathbb{E}[X^\omega]$. Finally, we note that
L001865	\begin{equation}
L001866		\sin\psi_k^\omega \sin(2 \pi k x+ \theta_k^\omega)=\sin\psi_k^\omega \cos(2 \pi k x + \tilde{\theta}_k^\omega)
L001867	\end{equation}
L001868	where $\tilde{\theta}_k^\omega=\theta_k^\omega+\pi \mod 2 \pi$ is a uniformly distributed random variable $[0,2 \pi]$. Therefore,
L001869	\begin{equation}
L001870		\sup_{x \in I} f(x) \sim_{\text{law}} X^\omega \sqrt{p}
L001871	\end{equation}
L001872	and we may focus on estimating $\mathbb{E}[X^\omega]$ from now on.
L001873	
L001874	\section{Canonical distance}
L001875	The main idea to follow is that the random process $\{f^\omega(x)\}_{x \in I}$ induces a (pseudo)-distance in its index space $x\in I$ given by
L001876	\begin{equation}\label{eq:Dudley}
L001877		d(x,y)\,:=\,\sqrt{\mathbb{E}[|f(x)-f(y)|^2]} \, , \qquad x,y \in I
L001878	\end{equation}
L001879	It is not a distance because, in principle, there can be pairs of points $x \neq y$ for which $d(x,y)=0$. To estimate the asymptotic properties of the shock time, we need to exploit geometric properties of the metric space $(I,d)$. The key notion is the one of \emph{metric entropy} $N(\varepsilon)$, that is the smallest number of balls (in the distance $d$) of radius $\varepsilon$ that cover $I$. In the '60s Dudley proved that if $\{f^{\omega}(x)\}_{x \in I}$ is a Gaussian process and $X$ is a compact space in the topology induced by the (pseudo-)distance $d$, then
L001880	\begin{equation}
L001881		\mathbb{E}[\sup_{x \in I} f^\omega(x)] \lesssim \int_0^{\mathrm{diam}_d(X)/2} \sqrt{\log N(\varepsilon)} \, d\varepsilon
L001882	\end{equation}
L001883	Such bounds were later extended to non-gaussian processes (with modifications on the RHS that contains the inverse function of the probability density function of the underlying process).
L001884	
L001885	Talagrand ***TIRARSELA UN PO' DI PIU'*** showed that the bound \eqref{eq:Dudley} is sharp for a large class of processes and, in particular, if they are Gaussian
L001886	\begin{equation}
L001887		\mathbb{E}[\sup_{x \in I} f^\omega(x)] \sim \int_0^{\mathrm{diam}_d(X)/2} \sqrt{\log N(\varepsilon)} \, d\varepsilon 1, .
L001888	\end{equation}
L001889	For our process, we have
L001890	\begin{equation}
L001891		\begin{split}
L001892			d(x,y)^2 &= \mathbb{E}[|f_p^\omega(x)-f_p^\omega(y)|^2] \qquad \text{(Stationary process)}\\
L001893			&=\frac{1}{2} S_2(p)-2 \mathbb{E}[f_p^\omega(x)f_p^\omega(y)] \qquad\text{(Independence)} \\
L001894			&=\frac{1}{2} S_2(p)-2 \sum_{k=1}^p k^2 \frac{1}{2} \mathbb{E}[\cos(2 \pi kx+\theta_k)\cos(2 \pi k y+\theta_k)] \\
L001895			&=\frac{1}{2}S_2(p)-\frac{1}{2}\sum_{k=0}^p k^2 \mathbb{E}[\cos(2 \pi k (x+y)+2 \theta_k)+\cos(2 \pi k (x-y))] \\
L001896			&=\frac{1}{2} S_2(p)- \frac{1}{2} \sum_{k=1}^p k^2 \cos(2 \pi k (x-y)) \\
L001897			&=\frac{1}{2} \sum_{k=1}^p k^2 (1-\cos(2 \pi k(x-y)))
L001898		\end{split}
L001899	\end{equation}
L001900	It is easy to show that $(I,d)$ is compact.
L001901	
L001902	To obtain bounds on the metric entropy of the process, we compare the distance $d$ with the Euclidean distance $d_E$.
L001903	\begin{equation}\label{eq:E444R}
L001904			d(x,y)^2 \lesssim_\delta \sum_{k=1}^p k^2\left(k d_E(x,y) \right)^\delta = d(x,y)^\delta \sum_{k=1}^p j^{2+\delta} =d_E(x,y)^\delta S_{2 +\delta}(p) \, \qquad \forall \delta >0
L001905	\end{equation}
L001906	Using this comparison, we can obtain bounds of the metric entropy $N_d(\varepsilon)$. To do so, let $M_d(\varepsilon)$ be the \emph{packing number}, i.e.~the greatest possible number of elements in an $\varepsilon$-distinguishable subset of $I$.\footnote{An $\varepsilon$-distinguishable set $\{x_j\}_{j \in I}$ is such that $d(x_j,x_{j'})\geq \varepsilon$ for all $j \neq j'$ in $I$.}
L001907	
L001908	In particular, it is possible to show that $M(\varepsilon) \leq N(\varepsilon/2) \leq M(\varepsilon/2)$.
L001909	
L001910	Using \eqref{eq:E444R}, we know that any $\varepsilon$-separated set in $(I,d)$ is $(\frac{\varepsilon}{S_{2+\delta}(p)})^{\frac{1}{\delta}}$-separated in $(I,d_E)$. In other words,
L001911	\begin{equation}
L001912		M_d(\varepsilon) \leq M_E((\varepsilon/S_{2+\delta}(p))^{\frac{1}{\delta}})) \sim \left(\frac{\varepsilon}{S_{2+\delta}(p)} \right)^{-\frac{1}{\delta}}
L001913	\end{equation}
L001914	Therefore, for any $\varepsilon>0$ and $\delta>0$, we have
L001915	\begin{equation}
L001916		N_d(\varepsilon) \lesssim \left(\frac{S_{2+\delta}(p)}{\varepsilon} \right)^{\frac{1}{\delta}}
L001917	\end{equation}
L001918	Using Dudley's bound
L001919	\begin{equation}
L001920		\begin{split}
L001921			\mathbb{E}[\sup_{x \in I} f_p^\omega(x)] &\lesssim \int_0^{S_2(p)} \sqrt{\frac{1}{\delta} \log(\frac{S_{2+\delta}(p)}{\varepsilon})} \, d\varepsilon \qquad \text{(change of coordinates $S_{2+\delta}(p)e^{-z}=\varepsilon$)}\\
L001922			&=\frac{1}{\sqrt{\delta}} \int_{\log (S_{2+\delta}(p))/S_2(p)} \sqrt{z} e^{-z} S_{2+\delta}(p) \, dz \\
L001923			&\lesssim \frac{1}{\sqrt{\delta}} S_{2+\delta}(p) \left(1+\sqrt{\log\frac{S_{2+\delta}(p)}{S_2(p)}} \right) \, .
L001924		\end{split}
L001925	\end{equation}
L001926	Since $S_q(p) \sim p^{q+1}$ we find that
L001927	\begin{equation}
L001928		\mathbb{E}[\sup_{x \in I} f_p^\omega(x) ] \lesssim \frac{1}{\sqrt{\delta}} p^{3+\delta} (1+\sqrt{\delta \log p}) \, .
L001929	\end{equation}
L001930	One can even choose $\delta=(\log p)^{-1}$ so that both terms are equal and thus
L001931	\begin{equation}
L001932		\mathbb{E}[\sup_{x \in I} \sum_{k=1}^p k \cos(2 \pi k x+ \theta_k)] \lesssim p^{3+\delta} \sqrt{\log p} \lesssim p^3 \sqrt{\log p}
L001933	\end{equation}
L001934	in view of the fact that $p^\delta=p^{(\log p)^{-1}}=e^{\log p/ \log p} = e $.
L001935	
L001936	
L001937	\vspace{0.2cm}
L001938	\noindent
L001939	\underline{Remark.} One can generalize this analysis for any coefficients $(a_k)_k$ by considering $\tilde{S}_2(p)=\sum_{k=1}^p a_k^2$ and $S_{2+\delta}(p)=\sum_{k=1}^p k^\delta a_k^2$.
L001940	
L001941	\vspace{0.2cm}
L001942	
L001943	We now discuss how to make Dudley's argument work even if our random variables are not gaussian.
L001944	
L001945	\section{Chaining argument and Dudley's bound}
L001946	In order to bound $\mathbb{E}[\sup_x f(x)]$ it is fundamental to bound the tails
L001947	\begin{equation}
L001948		\mathbb{P}[\sup_{x \in I} f(x) > \lambda]
L001949	\end{equation}
L001950	as $\lambda \to +\infty$. In fact, note that if $X \geq 0$ is any random variable, Fubini theorems implies
L001951	\begin{equation}
L001952		\mathbb{E}[X]=\int_0^{+\infty} \mathbb{P}(X>\lambda) \, d \lambda
L001953	\end{equation}
L001954	
L001955	In this spirit, if we wanted to bound
L001956	\begin{equation}\label{eq:StimaAPezzi}
L001957		\mathbb{P}(\max_{j=1}^n f(x_j) > \lambda) \leq \sum_{j=1}^n \mathbb{P}(f(x_i)>\lambda).
L001958	\end{equation}
L001959	The problem with this idea is that the RHS diverges as $n\to+\infty$. In order to consider the supremum over an infinite set, one needs to exploit the following ingredients
L001960	\begin{itemize}
L001961		\item[(i)] The stochastic process must be separable;
L001962		\item[(ii)] There is a large overlap between some sets $\{f(x_j)>\lambda\}$ and $\{f(x_i) > \lambda \}$ if $x_i$ is close to $x_j$. This means that \eqref{eq:StimaAPezzi} is wasteful and we can do better.
L001963	\end{itemize}
L001964	Point (i) follows from the continuity of $f$, which in turn follows from the Kolmogorov continuity theorem. Two points being ``close'' one to each other is best measured in the \emph{canonical distance}.
L001965	
L001966	\begin{lemma}
L001967		Let $f$ be our process, then
L001968		\begin{equation}
L001969			\mathbb{P}(f(x)-f(y) > \lambda) \leq 2 \exp(-\frac{\lambda^2}{8 d(x,y)^2}
L001970		\end{equation}
L001971	\end{lemma}
L001972	\begin{proof}
L001973	
L001974	\end{proof}
